==🏛️ *B2G Tender Alert — ZTE Indonesia*
📅 {{ $now.toFormat('dd MMM yyyy, HH:mm') }} WIB  |  Source: {{ $json.data.data[0].data.data.data_source.platform }}
🔍 Items reviewed: {{ $json.data.data[0].data.data.search_methodology.total_items_reviewed }}

━━━━━━━━━━━━━━━━━━━━━━
📊 *PIPELINE SNAPSHOT*
🔴 {{ $json.data.data[0].data.data.executive_summary.high_priority_opportunities }} High  |  🟡 {{ $json.data.data[0].data.data.executive_summary.medium_priority_opportunities }} Medium  |  🟢 {{ $json.data.data[0].data.data.executive_summary.low_priority_opportunities }} Low
💰 Total Value: *Rp {{ $json.data.data[0].data.data.executive_summary.total_value_idr.toLocaleString('id-ID') }}*

🔑 *Key Findings:*
{{ $json.data.data[0].data.data.executive_summary.key_findings.map((f,i) => `${i+1}. ${f}`).join('\n') }}

📌 *Market Insights:*
{{ $json.data.data[0].data.data.executive_summary.market_insights.map(m => `• ${m}`).join('\n') }}

━━━━━━━━━━━━━━━━━━━━━━
🎯 *TENDER OPPORTUNITIES*
{{ $json.data.data[0].data.data.zte_relevant_opportunities.map(opp => {
  const e = opp.priority === 'HIGH' ? '🔴' : opp.priority === 'MEDIUM' ? '🟡' : '🟢';
  const budget = opp.budget?.idr ? `Rp ${Number(opp.budget.idr).toLocaleString('id-ID')} (~USD ${Number(opp.budget.usd_approx).toLocaleString()})` : 'Not disclosed';
  const solutions = opp.zte_relevance?.applicable_solutions?.join(', ') || 'Not available';
  const fit = opp.zte_relevance?.business_fit_rationale || opp.zte_relevance?.why_relevant || 'Not available';
  const signals = opp.b2b_signals?.strategic_signal || 'Not available';
  const url = opp.source_url || 'Not available';
  return `${e} *${opp.title}*
   🏢 ${opp.organization}
   🏭 Sector: ${opp.sector}  |  🔄 Stage: ${opp.project_stage}
   💰 Budget: ${budget}
   ⏰ Timeline: ${opp.timeline}
   📝 Scope: ${opp.scope}
   📦 ZTE Solutions: ${solutions}
   💡 Why it matters: ${fit}
   📶 Signals: ${signals}
   🔗 Source: ${url}`;
}).join('\n\n─────────────────────\n\n') }}

━━━━━━━━━━━━━━━━━━━━━━
💡 *RECOMMENDED ACTIONS*
{{ $json.data.data[0].data.data.recommendations?.immediate_actions?.map((a,i) => `${i+1}. ${a}`).join('\n') || $json.data.data[0].data.data.recommendations?.for_zte?.map((a,i) => `${i+1}. ${a}`).join('\n') }}

_ZTE Sales Intelligence Platform_

==📡 *B2B Market Signal — ZTE Indonesia*
📅 {{ $now.toFormat('dd MMM yyyy, HH:mm') }} WIB  |  {{ $json.data.data.extraction_metadata.total_articles_analyzed }} articles analyzed

━━━━━━━━━━━━━━━━━━━━━━
📊 *PIPELINE SNAPSHOT*

🔴 Confirmed    {{ $json.data.data.executive_summary.signal_strength_distribution.confirmed_projects || 0 }}
🟠 Procurement  {{ $json.data.data.executive_summary.signal_strength_distribution.procurement_stage || 0 }}
🟡 Planning     {{ $json.data.data.executive_summary.signal_strength_distribution.planning_stage || 0 }}
🟢 Early Signal {{ $json.data.data.executive_summary.signal_strength_distribution.early_signals || 0 }}

━━━━━━━━━━━━━━━━━━━━━━
🎯 *B2B OPPORTUNITIES*
{{ 
(
  $json.data?.data?.zte_relevant_opportunities ||
  $json.data?.zte_relevant_opportunities ||
  []
).map(opp => {
  const priority = (opp.priority || '').toLowerCase();
  const e = priority === 'critical' ? '🔴 CRITICAL' : priority === 'high' ? '🟠 HIGH' : priority.includes('medium') ? '🟡 MEDIUM' : '🟢 LOW';
  const stage = opp.b2b_signals?.decision_stage || '-';
  const scope = opp.opportunity_description?.scope || '-';
  const technologies = opp.b2b_signals?.technologies_required?.join(', ') || '-';
  const solutions = opp.zte_relevance?.applicable_solutions?.join(', ') || '-';
  const fit = opp.zte_relevance?.business_fit_rationale || '-';
  return `${e} — *${opp.title || '-'}*\n   🏢 Buyer: ${opp.buyer_profile?.buyer_name || '-'}\n   🔄 Stage: ${stage}\n   🌍 Scope: ${scope}\n   🔧 Technologies: ${technologies}\n   📦 ZTE Solutions: ${solutions}\n   💡 Fit: ${fit}`;
}).join('\n\n─────────────────────\n\n') || 'No opportunities found'
}}

━━━━━━━━━━━━━━━━━━━━━━
⚡ *THIS WEEK FOR SALES*
{{ $json.data.data.strategic_recommendations.immediate_actions.map((a,i) => `${i+1}. ${a}`).join('\n') }}

_ZTE Sales Intelligence Platform_
